      "achados": [
        {
          "proposicao": "No FPSO citado, a água oleosa proveniente dos hidrociclones e o material coletado na célula de flutuação eram enviados por drenagem isolada para reprocessamento no separador de produção, indicando recirculação de correntes fora da condição desejada em vez de descarte direto.",
          "trechos": [
            "E59ab145054853124:0:688"
          ],
          "condicoes": [
            "no arranjo operacional do FPSO Frade descrito para 2011"
          ],
          "limites": [
            "trata-se de descrição de instalação específica",
            "a fonte não informa critérios automáticos de desvio, gatilhos de controle nem desempenho quantitativo"
          ]
        },
        {
          "proposicao": "O mecanismo de separação no hidrociclone é descrito como resultado de escoamento circular em alta velocidade, gerando força centrípeta que desloca a fase aquosa mais densa para a periferia e concentra o óleo menos denso no núcleo central.",
          "trechos": [
            "E59ab145054853124:688:1387"
          ],
          "condicoes": [
            "para o princípio de funcionamento do hidrociclone referido na nota técnica do relatório"
          ],
          "limites": [
            "a fonte não quantifica faixa de gota, eficiência, turndown ou sensibilidade a variações de carga"
          ]
        },
        {
          "proposicao": "A saída das correntes no hidrociclone depende também de pressão traseira na descarga de água, que força a reversão da corrente oleosa para a outra extremidade pelo orifício de rejeição.",
          "trechos": [
            "E59ab145054853124:688:1387"
          ],
          "condicoes": [
            "conforme o princípio operacional resumido na fonte"
          ],
          "limites": [
            "a fonte não define valores de diferencial de pressão, split nem faixas operacionais"
          ]
        }
      ]
    },
