      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A escolha da tecnologia de tratamento da água produzida depende do espaço disponível, da aplicação, da disponibilidade de produtos químicos e das características do efluente.",
          "trechos": [
            "E2c41a76d63554119:0:698"
