          ]
        },
        {
          "proposicao": "Em plataformas offshore, a combinação de hidrociclones seguidos de flotadores é apontada como comum devido à limitação de espaço, às características da produção e à necessidade de enquadramento para descarte.",
          "trechos": [
            "E2c41a76d63554119:0:698"
          ],
          "condicoes": [
            "especialmente para instalações offshore conforme a comparação da fonte"
